package com.xiaoxiao.pet;

import android.app.*;import android.content.*;import android.graphics.Color;import android.os.Build;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;

/** A single stationary panel owns both category navigation and action selection. */
final class ActionSheet {
 final Context context;final PetService.Pet pet;final Dialog dialog;final LinearLayout rows;final ScrollView scroll;final TextView title;final Button back;final boolean menu;final Runnable finished;
 ActionSheet(Context c,PetService.Pet p,boolean includeMenu,Runnable finished){context=c;pet=p;menu=includeMenu;this.finished=finished;dialog=CompactPanel.create(c);LinearLayout content=new LinearLayout(c);content.setOrientation(1);content.setPadding(dp(12),dp(8),dp(12),dp(8));LinearLayout top=new LinearLayout(c);top.setGravity(Gravity.CENTER_VERTICAL);back=new Button(c);back.setText("返回");Apple.button(back,false);top.addView(back,new LinearLayout.LayoutParams(dp(64),dp(44)));title=Apple.label(c,Data.name(p.role),17,true);title.setGravity(Gravity.CENTER);title.setMaxLines(2);top.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));Button close=new Button(c);close.setText("关闭");Apple.button(close,false);top.addView(close,new LinearLayout.LayoutParams(dp(64),dp(44)));close.setOnClickListener(v->dialog.dismiss());content.addView(top);View line=new View(c);line.setBackground(Apple.shape(c,Apple.LINE,0));LinearLayout.LayoutParams separator=new LinearLayout.LayoutParams(-1,dp(1));separator.topMargin=dp(8);content.addView(line,separator);scroll=new SpringScrollView(c);scroll.setFillViewport(true);rows=new LinearLayout(c);rows.setOrientation(1);scroll.addView(rows);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView hint=Apple.label(c,c instanceof Activity?"选择后播放，离开控制页可查看角色。":"选择动作后立即播放。",12,false);hint.setTextColor(Apple.SECONDARY);hint.setPadding(0,dp(10),0,0);content.addView(hint);dialog.setContentView(content);Window win=dialog.getWindow();win.setTitle("小小桌宠-动作菜单");if(!(c instanceof Activity))win.setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);win.setGravity(Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);win.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);dialog.setOnDismissListener(d->{if(finished!=null)finished.run();});back.setOnClickListener(v->home());dialog.setOnKeyListener((d,key,event)->{if(key==android.view.KeyEvent.KEYCODE_BACK&&event.getAction()==android.view.KeyEvent.ACTION_UP&&back.getVisibility()==View.VISIBLE){home();return true;}return false;});home();}
 int dp(int x){return Apple.dp(context,x);}
 void show(){CompactPanel.show(dialog,context,pet,"小小桌宠-动作菜单");}
 void row(String text,View.OnClickListener click){Button b=new Button(context);b.setText(text);Apple.button(b,false);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setTextSize(16);LinearLayout.LayoutParams a=new LinearLayout.LayoutParams(-1,dp(48));a.topMargin=dp(8);rows.addView(b,a);b.setOnClickListener(click);}
 void reset(String heading,boolean nested){title.setText(heading);rows.removeAllViews();back.setVisibility(nested?View.VISIBLE:View.INVISIBLE);scroll.scrollTo(0,0);rows.post(()->UiMotion.enter(rows));}
 void home(){reset(Data.name(pet.role),false);if(menu)row("对话",v->{dialog.dismiss();Chat.show(context,pet.role,pet.id);});for(Map.Entry<String,String> group:Data.menuGroups(pet.role).entrySet())row(group.getKey(),v->category(group.getKey(),group.getValue()));if(!menu){row("恢复待机",v->{pet.play(Data.idle(pet.role));});row(pet.rotation?"关闭动作轮播":"开启动作轮播",v->{pet.rotation=!pet.rotation;pet.nextAction=android.os.SystemClock.uptimeMillis()+5000;PetService.instance.save();home();});}if(menu){row(pet.rotation?"关闭动作轮播":"开启动作轮播",v->{pet.rotation=!pet.rotation;pet.nextAction=android.os.SystemClock.uptimeMillis()+5000;PetService.instance.save();home();});row("恢复待机",v->{pet.play(Data.idle(pet.role));});row("缩小",v->pet.resize((int)(pet.width*.85f)));row("放大",v->pet.resize((int)(pet.width*1.15f)));row("隐藏此角色",v->{pet.hide();PetService.instance.save();dialog.dismiss();});}}
 void category(String label,String key){reset(label,true);JSONArray actions=Data.role(pet.role).optJSONObject("groups").optJSONArray(key);if(actions==null)return;LinkedHashSet<String> unique=new LinkedHashSet<>();for(int i=0;i<actions.length();i++)unique.add(actions.optString(i));for(String action:unique)row(action,v->{PetService s=PetService.instance;if(s==null)return;pet.visible=true;pet.attach();s.control(MainActivity.active);s.save();pet.play(action);for(int i=0;i<rows.getChildCount();i++){View item=rows.getChildAt(i);item.setSelected(item==v);item.setBackground(Apple.shape(context,item==v?Apple.TINT:Apple.PANEL,12));}});}
}
